            total_reward += reward
            if done:
                success = True
                break
            state = next_state
        if success:
            successes += 1
        episode_records.append(
            {
                "trace": trace,
                "total_reward": total_reward,
                "success": success,
            }
        )
    return {
        "episodes": episode_records,
        "success_rate": successes / episodes,
